import sys; sys.path.insert(0, __file__.rsplit('/',1)[0])
from prove_common import *
R=Run('a-navigation-filters-persistence')
with sync_playwright() as p:
    b=p.chromium.launch(executable_path=os.environ['RENDER_SHELL']); ctx=b.new_context(viewport={'width':1440,'height':900}, accept_downloads=True); pg=ctx.new_page(); R.attach(pg); E=pg.evaluate
    pg.goto(URL); pg.wait_for_timeout(900)
    R.check('fresh load opens the overview', E("()=>CEO_APP.state.view")=='overview')
    views=['overview','accounts','liquidity','payments','fx','risk','trade','reports','messages','settings']
    for v in views:
        pg.click('.sh-body > .sn a.sn-link[data-view="%s"]'%v); pg.wait_for_timeout(500)
        r=E("(v)=>({vis:[...document.querySelectorAll('.ceo-view')].filter(s=>!s.hidden).map(s=>s.dataset.view), cur:document.querySelector('.sh-body > .sn a[aria-current=page]').dataset.view, h1:document.querySelector('.ph-title').textContent, url:location.search, focus:document.activeElement.id, figs:[...document.querySelectorAll('#view-'+v+' figure.dv')].map(f=>(f.getAttribute('data-ceo-error')?'ERR':'')+f.querySelectorAll('.dv-series').length), errs:CEO_APP.renderErrors.concat(CEO_APP.chartErrors)})", v)
        R.check('nav → %s: one view shown, nav current, title, URL, focus to title, charts drawn'%v, r['vis']==[v] and r['cur']==v and ('view='+v) in r['url'] and r['focus']=='ceo-title' and all(x.isdigit() and int(x)>0 for x in r['figs']) and not r['errs'], r)
    pg.click('.sh-body > .sn a.sn-link[data-view="overview"]'); pg.wait_for_timeout(500)
    k0=E("()=>[...document.querySelectorAll('#view-overview .kpi-val')].map(e=>e.textContent)")
    s0=E("()=>JSON.stringify(document.querySelector('#t-ov-c-exposure figure').__dvSpec.series)")
    pg.click('#ftbAddT'); pg.wait_for_timeout(150); pg.click('#ftbAddM .opt[data-facet="region"][data-value="APAC"]'); pg.wait_for_timeout(500)
    k1=E("()=>[...document.querySelectorAll('#view-overview .kpi-val')].map(e=>e.textContent)")
    s1=E("()=>JSON.stringify(document.querySelector('#t-ov-c-exposure figure').__dvSpec.series)")
    R.check('region filter re-drives KPIs', k0!=k1, [k0,k1])
    R.check('region filter re-drives the exposure chart', s0!=s1)
    R.check('filter chip shown and results count answered', E("()=>[...document.querySelectorAll('#ftbChipsA .tag .lbl')].map(e=>e.textContent).join()")=='Region: Asia Pacific' and E("()=>document.getElementById('ceo-consumer').getAttribute('data-apollo-result-count')")!=None)
    pg.click('#ftbAddT'); pg.wait_for_timeout(150); pg.click('#ftbAddM .opt[data-facet="currency"][data-value="SGD"]'); pg.wait_for_timeout(500)
    R.check('second facet (currency) combines with region', E("()=>CEO_APP.state.filters.length")==2)
    pg.click('#ftbRangeT'); pg.wait_for_timeout(150); pg.click('#ftbRangeM .opt[data-days="7"]'); pg.wait_for_timeout(500)
    R.check('date range 7 days re-drives the time series (7 categories)', E("()=>document.querySelector('#t-ov-c-trend figure').__dvSpec.categories.length")==7)
    pg.fill('#ftbQ','Kestrel'); pg.wait_for_timeout(500)
    R.check('search is written to state and URL', 'q=Kestrel' in E("()=>location.search"))
    pg.click('.sh-body > .sn a.sn-link[data-view="risk"]'); pg.wait_for_timeout(600)
    R.check('filters are shared: risk positions honour region + currency + search', E("()=>document.querySelector('#t-rk-r-positions').__rec.rows.every(p=>p.region==='APAC'&&p.ccy==='SGD'&&/kestrel/i.test(p.counterparty+p.id+p.instrument+p.ccy))"))
    pg.reload(); pg.wait_for_timeout(1000)
    r=E("()=>[CEO_APP.state.view, CEO_APP.state.filters.length, CEO_APP.state.days, CEO_APP.state.q, [...document.querySelectorAll('#ftbChipsA .tag .lbl')].length, document.querySelector('#ftbQ').value, document.querySelector('#ftbRange .ddval').textContent]")
    R.check('reload restores view, filters (chips), range and search', r==['risk',2,7,'Kestrel',2,'Kestrel','Last 7 days'], r)
    pg.click('[data-ftb-clear]'); pg.wait_for_timeout(500)
    R.check('clear all removes filters and search', E("()=>[CEO_APP.state.filters.length, CEO_APP.state.q]")==[0,''])
    pg.click('#ftbRangeT'); pg.wait_for_timeout(150); pg.click('#ftbRangeM .opt[data-days="30"]'); pg.wait_for_timeout(400)
    pg.click('.sh-body > .sn a.sn-link[data-view="overview"]'); pg.wait_for_timeout(600)
    pg.click('#t-ov-c-exposure rect.dv-series >> nth=0', position={'x':6,'y':6}); pg.wait_for_timeout(700)
    r=E("()=>[CEO_APP.state.view, CEO_APP.state.filters, document.querySelector('#t-rk-r-positions').__rec.rows.length, document.querySelector('#t-rk-r-positions').__rec.rows.every(p=>p.region===CEO_APP.state.filters[0].value)]")
    R.check('overview exposure column drills through to risk positions for that region', r[0]=='risk' and r[1][0]['facet']=='region' and r[3], r)
    pg.go_back(); pg.wait_for_timeout(600)
    R.check('browser back returns to the overview', E("()=>CEO_APP.state.view")=='overview')
    pg.click('[data-ftb-clear]'); pg.wait_for_timeout(400)
    pg.click('#t-ov-c-ccy path.dv-series >> nth=0'); pg.wait_for_timeout(700)
    R.check('currency donut slice drills through to risk with a currency filter', E("()=>[CEO_APP.state.view, CEO_APP.state.filters.map(f=>f.facet).join()]")==['risk','currency'])
    pg.click('[data-ftb-clear]'); pg.wait_for_timeout(400)
    pg.click('.sh-actions .seg button[data-value="dark"]'); pg.wait_for_timeout(400)
    R.check('theme switch sets data-theme=dark and the Common theme stays on', E("()=>[document.documentElement.dataset.theme, document.documentElement.getAttribute('data-apollo-theme')]")==['dark','common'])
    pg.reload(); pg.wait_for_timeout(900)
    R.check('dark theme persists across reload', E("()=>document.documentElement.dataset.theme")=='dark')
    R.check('the dark masterbrand mark shows in dark mode', E("()=>[...document.querySelectorAll('.sh-appbar img.sh-mark')].filter(i=>getComputedStyle(i).display!=='none').map(i=>i.dataset.mode+':'+i.naturalWidth).join()")=='dark:315')
    pg.click('.sh-actions .seg button[data-value="light"]'); pg.wait_for_timeout(300)
    pg.click('.sh-body > .sn a.sn-link[data-view="payments"]'); pg.wait_for_timeout(600)
    with pg.expect_download() as d:
        pg.click('#ftbExportT'); pg.wait_for_timeout(150); pg.click('#ftbExportM .opt[data-format="csv"]')
    f=W+'/tmp/'+d.value.suggested_filename; d.value.save_as(f); txt=open(f).read()
    R.check('export CSV downloads the current view\'s records', d.value.suggested_filename=='payments.csv' and txt.count('\n')>=95, [d.value.suggested_filename, txt.count('\n')])
    with pg.expect_download() as d:
        pg.click('#ftbExportT'); pg.wait_for_timeout(150); pg.click('#ftbExportM .opt[data-format="xlsx"]')
    R.check('export Excel downloads an Excel-readable table', d.value.suggested_filename=='payments.xls')
    pg.click('.sh-actions button[aria-label="Search"]'); pg.wait_for_timeout(200)
    R.check('app-bar search button focuses the filter bar search', E("()=>document.activeElement.id")=='ftbQ')
    pg.click('.sn-toggle[data-navtoggle]'); pg.wait_for_timeout(400)
    R.check('nav collapses to the 64px rail with names kept', E("()=>[Math.round(document.querySelector('.sh-body > .sn').getBoundingClientRect().width), document.querySelector('.sh-body > .sn').getAttribute('aria-label')]")==[64,'Main, collapsed'])
    pg.click('.sn-toggle[data-navtoggle]'); pg.wait_for_timeout(300)
    pg.set_viewport_size({'width':700,'height':900}); pg.wait_for_timeout(500)
    pg.click('.sh-menu'); pg.wait_for_timeout(600)
    R.check('phone width: menu opens the nav sheet with focus inside', E("()=>[document.querySelector('.sh-sheet').classList.contains('open'), !!document.activeElement.closest('.sh-sheet')]")==[True,True])
    pg.keyboard.press('Escape'); pg.wait_for_timeout(300)
    R.check('Escape closes the sheet and returns focus to the menu button', E("()=>[document.querySelector('.sh-sheet').classList.contains('open'), document.activeElement.classList.contains('sh-menu')]")==[False,True])
    R.save(); b.close()
